      + '<section class="og" id="ord-scad" data-n="' + nScad + '">' + ordScadHtml(F.att) + '</section>'
      + (B.rip.length ? '<section class="og" id="ord-rip" data-n="' + F.rip.length + '">' + ordRipHtml(F.rip) + '</section>' : '');
