      + '</optgroup>';

    var list = CMv().filter(cmatch);
    list.sort(function(a,b){ return String(a.code||'').localeCompare(String(b.code||'')); });
    var nsel = selected().length;
    var nev = nEvase(), nsp = nSosp(), natt = CM().length - nev - nsp;

    var h = '<div class="cm-tools">'
      + '<div class="seg sub"><button id="cv-att" aria-pressed="' + (cview === 'attive') + '">'
      + 'In corso · ' + natt + '</button>'
      + '<button id="cv-sp" aria-pressed="' + (cview === 'sospese') + '">Sospese · ' + nsp + '</button>'
      + '<button id="cv-ev" aria-pressed="' + (cview === 'evase') + '">Evase · ' + nev + '</button></div>'
      + '<div class="seg sub"><button id="cm-schede" aria-pressed="' + (cmode === 'schede') + '">Schede</button>'
      + '<button id="cm-gantt" aria-pressed="' + (cmode === 'gantt') + '">Gantt</button>'
      + '<button id="cm-ord" aria-pressed="' + (cmode === 'ordini') + '">Ordini'
      + (function(n){ return n ? ' · ' + n + ' scad.' : ''; })(ordScadN(nsel ? selected() : list)) + '</button>'
      + '<button id="cm-cash" aria-pressed="' + (cmode === 'cash') + '">Cash flow</button>'
      + '<button id="cm-scad" aria-pressed="' + (cmode === 'scad') + '">Scadenze'
      + (scadCount() ? ' · ' + scadCount() : '') + '</button>'
      + '<button id="cm-cli" aria-pressed="' + (cmode === 'clienti') + '">Clienti</button>'
      + '<button id="cm-ctr" aria-pressed="' + (cmode === 'ctr') + '">Contratti</button>'
      + '<button id="cm-bdg" aria-pressed="' + (cmode === 'bdg') + '">Budget'
      + (bdgDaConfermare(list).length ? ' \u00b7 ' + bdgDaConfermare(list).length + ' da conf.' : '') + '</button></div>'
      + '<input class="sel" id="cq" type="search" placeholder="Cerca codice, cliente, paese…" '
      + 'value="' + esc(cq) + '" aria-label="Cerca commessa" style="min-width:230px">'
      + '<select class="sel" id="cfilt" aria-label="Filtro">' + opts + '</select>'
      + '<button class="chip" id="c-all">Apri i ' + list.length + ' visibili</button>'
      + '<button class="chip" id="c-none">Pulisci selezione</button>'
      + '<span class="cm-hint">' + (nsel ? nsel + ' commesse aperte a confronto'
          : (cview === 'evase' ? 'archivio delle commesse chiuse: restano qui, non spariscono'
             : cview === 'sospese' ? 'commesse ferme in attesa di una condizione: incasso, approvazione, decisione del cliente'
             : 'clicca una o più commesse per aprirle a confronto')) + '</span></div>';

    if (list.length){
      h += '<div class="picker">';
      list.forEach(function(c){
        var st = stato(c);
        h += '<button class="pk' + (c.ev ? ' ev' : '') + (c.sp ? ' sp' : '') + '" data-code="' + esc(c.code)
          + '" aria-pressed="' + (sel[c.code] ? 'true' : 'false') + '">'
          + '<span class="flag f-' + (c.ev ? 'done' : c.sp ? 'sp' : st.k) + '" title="'
          + esc(c.ev ? 'evasa' : c.sp ? 'sospesa' : st.txt) + '"></span>'
          + '<b>' + esc(c.code) + '</b><span class="n">' + esc(c.cliente) + '</span></button>';
      });
      h += '</div>';
    } else if (cview === 'evase'){
      h += '<div class="ore-wait" style="margin-bottom:20px">Nessuna commessa evasa per ora. '
        + 'Quando ne chiudi una, spuntala nella colonna <b>Evasa</b> della tabella o dalla sua scheda: '
        + 'finisce qui e sparisce dall\'elenco delle commesse in corso, senza essere cancellata.</div>';
    } else if (cview === 'sospese'){
      h += '<div class="ore-wait" style="margin-bottom:20px">Nessuna commessa sospesa. '
        + 'Spunta <b>Sosp.</b> in tabella, o usa il pulsante nella scheda, per mettere da parte una commessa '
        + 'ferma in attesa di un incasso, di un\'approvazione o di una decisione del cliente: esce dall\'elenco '
        + 'delle in corso ma resta viva, con la data in cui l\'hai sospesa.</div>';
    }

    var pool = nsel ? selected() : list;
    h += kpiBar(pool, nsel);
    if (cmode === 'ordini') h += ordiniHtml(nsel ? selected() : list, nsel);
    else if (cmode === 'gantt') h += ganttHtml(nsel ? selected() : list);
    else if (cmode === 'clienti') h += clientiHtml(nsel ? selected() : list);
    else if (cmode === 'ctr') h += contrattiHtml(nsel ? selected() : list);
    else if (cmode === 'cash') h += cashHtml(nsel ? selected() : list, nsel);
    else if (cmode === 'bdg') h += bdgHtml(nsel ? selected() : list, nsel);
    else if (cmode === 'scad') h += scadHtml(nsel ? selected() : list);
    else h += nsel ? cmCards(selected()) : cmTable(list);
    stage.innerHTML = h;
    cmxDopo();   /* R35: Gantt di portafoglio alla larghezza vera, indice delle schede sotto la barra */
