      + '<line x1="' + xa.toFixed(1) + '%" x2="' + xb.toFixed(1) + '%" y1="12" y2="12" stroke="var(' + (late ? '--late' : '--vz-1') + ')" stroke-width="' + (late ? 3 : 2) + '"/>';
