    var gg = 0, m = t.match(/(?:entro|within)\s+(\d{1,3})\s*(?:giorni|gg|days)/) || t.match(/(\d{1,3})\s*(?:giorni|gg|days)\s+(?:dalla|dal|dopo|from|after)/);
