  var db = null, sample = null, prefRef = null;
  var state = { runs: [], giorni: [], richieste: [], regole: [], proposte: [], prefs: null, cfg: null, profilo: null };

  /* ---------- innesto nella dashboard: scheda POSTA + KPI hero ---------- */
  var stage = $('stage');
